(()=>{function enhance(){document.querySelectorAll('.branding-block').forEach(block=>{if(block.dataset.egressNote)return;block.dataset.egressNote='1';const logo=block.querySelector('.brand-logo');if(logo){const label=logo.closest('.field')?.querySelector('label');if(label)label.textContent='Dedicated mobile / white-label logo URL (HTTPS)';const note=document.createElement('div');note.className='muted brand-egress-note';note.textContent='Portal+ Web uses the brand name, accent colour and a generated brand mark without external image egress. The logo URL is reserved for native/dedicated clients unless a future web-logo hosting option is enabled.';logo.closest('.field')?.appendChild(note);}});}new MutationObserver(enhance).observe(document.getElementById('experiences'),{childList:true,subtree:true});window.addEventListener('DOMContentLoaded',enhance);})();